import { Transform } from 'class-transformer';
import { IsEmail, IsString, MaxLength } from 'class-validator';

// POST /businesses/:id/admins (SUPER_ADMIN only). Strict whitelist: the ONLY thing the caller chooses is the email. The
// business comes from the URL, the role is always ADMIN, the password is generated by the server, and
// must_change_password / credentials_version / active are decided by the server — anything else in the body (password,
// role, businessId, mustChangePassword...) is a 400 (the global ValidationPipe forbids non-whitelisted properties).
// The email is normalised exactly like the login does (trim + lowercase), so the stored address is the one the login looks up.
export const ADMIN_EMAIL_MAX_LENGTH = 254;

const normalizeEmail = ({ value }: { value: unknown }): unknown => (typeof value === 'string' ? value.trim().toLowerCase() : value);

export class CreateBusinessAdminDto {
  @Transform(normalizeEmail)
  @IsString()
  @MaxLength(ADMIN_EMAIL_MAX_LENGTH)
  @IsEmail()
  email: string;
}
